import{_ as t,a}from"./chunks/2db7696652d1d34bdcbc.CVr6XeoV.js";import{_ as o,C as i,o as p,c as n,j as r,a as s,E as h,a5 as c}from"./chunks/framework.DNkHA0lr.js";const y=JSON.parse('{"title":"4小时的专注工作将改变你的一生","description":"","frontmatter":{"title":"4小时的专注工作将改变你的一生","originalTitle":"4 Hours Of Focused Work Will Change Your Life","date":"2021-08-28","originalUrl":"https://thedankoe.com/letters/4-hours-of-focused-work-will-change-your-life/","minutes":5,"sourceHash":"34de9d129ec6a4c481246f00755cf9bd8cfdbc9e62f4b7aac462904eaf14cebc","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/4-hours-of-focused-work-will-change-your-life/"}]]},"headers":[],"relativePath":"letters/4-hours-of-focused-work-will-change-your-life.md","filePath":"letters/4-hours-of-focused-work-will-change-your-life.md"}'),u={name:"letters/4-hours-of-focused-work-will-change-your-life.md"};function f(d,e,m,_,g,b){const l=i("ArticleMeta");return p(),n("div",null,[e[0]||(e[0]=r("h1",{id:"_4小时的专注工作将改变你的一生",tabindex:"-1"},[s("4小时的专注工作将改变你的一生 "),r("a",{class:"header-anchor",href:"#_4小时的专注工作将改变你的一生","aria-label":'Permalink to "4小时的专注工作将改变你的一生"'},"​")],-1)),h(l),e[1]||(e[1]=c('<p><a href="https://www.youtube.com/embed/CvsnW06-yNY?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>能够随心所欲地刻意引导你的注意力，不仅能为你节省时间，还能为你省钱（参见：<a href="https://markmanson.net/attention" target="_blank" rel="noreferrer">注意力经济</a>）。</p><ul><li>主流新闻媒体通过恐惧来将你的注意力变现。</li><li>社交媒体账号通过“产生共鸣”且往往是自嘲的表情包来窃取你的注意力。</li><li>Twitter、Instagram 和 Facebook 完全清楚什么颜色、话题和内容分发方式能让你上头。</li><li>总有一些东西来填补无聊带来的空虚。</li><li>就在刚才，我点开看了眼我的 Twitter 通知。</li></ul><p>从自上而下的视角来看，这就是现代世界面临的巨大问题。</p><p>在心理健康方面，人们关注自己的想法，而不是想法背后的原因。</p><p>在身体健康方面，人们关注短期的快感，而不是长期的精力。</p><p>在财务健康方面，人们关注赚快钱的套路，而不是可持续的业务增长。</p><p>我们不是来谈论这些的。我们是来谈论专注工作的，但你可以看到注意力经济所制造的问题。</p><p>专注力是一种货币，我们必须明智地投资它。</p><h2 id="最小风险-潜在回报" tabindex="-1">最小风险，潜在回报 <a class="header-anchor" href="#最小风险-潜在回报" aria-label="Permalink to &quot;最小风险，潜在回报&quot;">​</a></h2><p>注意力经济只有当你处于消费者端时，才是灾难性的。</p><p>机会如野草般涌现，为了抓住它们，你需要去生产创造。</p><p>你需要把注意力集中在构建风险极小、但有潜力获得巨大回报的事物上。</p><p>这被称为非对称下注（asymmetric bets）。</p><p><img src="'+t+'" alt="Asymmetric Bets Illustration"></p><p>非对称下注</p><p>过去 5-10 年涌现的一些机会（你现在依然可以抓住）：</p><ul><li>加密货币</li><li>建立社交媒体受众</li><li>提供细分领域的自由职业服务</li><li>创办一家营销机构</li><li>将你的专业知识产品化并在网上销售</li><li>开办播客或博客</li></ul><p>4 年前，我开始做网页设计的自由职业。这不需要花一分钱，只需在 YouTube 上花点时间学习就能做，但它有潜力替代你的主业收入。</p><p>1年半前，我开通了一个 Twitter 账号，现在已经涨到了 4 万粉丝，这让我得以跳出为客户代劳的接单工作。</p><p>现在，我正处于做博客、YouTube 频道和播客的起步阶段。只要我遵循正确的公式，我毫不怀疑这些将带来巨大的回报。</p><blockquote><p>公式：微小的初期投资 + 坚持 + 迭代 = 指数级回报。</p></blockquote><p>我的成功，无论大小，完全建立在非对称下注之上。</p><p>造就这些结果的载体是什么？专注工作。</p><p>也就是，把我的专注力投资到注意力经济的“股市”里，通过每次1小时的专注，为世界提供价值。</p><h2 id="_4-小时比你想象的要多" tabindex="-1">4 小时比你想象的要多 <a class="header-anchor" href="#_4-小时比你想象的要多" aria-label="Permalink to &quot;4 小时比你想象的要多&quot;">​</a></h2><p>我的好朋友乔伊（Joey，<a href="https://twitter.com/psypreneur" target="_blank" rel="noreferrer">@heyjoeyjustice</a>）是一名心理表现教练。</p><p>他和许多其他人已经证明，通过专注，你可以把工作时间砍半。</p><p>在4小时专注状态下完成的工作，比在8小时分心状态下完成的还要多。</p><p>哪怕只是1小时的专注工作也能带来很好的回报，特别是对于那些还有其他耗时事务要处理的人来说。</p><p>要开始你的下注，有一个先决条件。</p><p>你必须有想要追求的兴趣或好奇心。如果你不主动学习，就很难找到可以变现的机会。</p><p>一旦你学到了，就必须在现实世界中去执行。</p><h3 id="joey-进入专注状态的-3-个步骤" tabindex="-1">Joey 进入专注状态的 3 个步骤 <a class="header-anchor" href="#joey-进入专注状态的-3-个步骤" aria-label="Permalink to &quot;Joey 进入专注状态的 3 个步骤&quot;">​</a></h3><p>在我们开始之前——拿一个实体笔记本和一支笔。</p><p><strong>步骤 1) 大脑清空（Brain Dump）</strong></p><p>这有两个目的：</p><ol><li>清除内心的干扰（想法和点子）</li><li>明确你在特定项目中需要完成的具体任务</li></ol><p>放手去写，把脑子里冒出来的所有东西都写下来。这不仅限于“工作”。</p><p>写下从家庭琐事到这周购物清单的所有事情（以及你为了“工作”必须做的事情）。</p><p><strong>步骤 2) 分类与排定优先级</strong></p><p>为任务创建相应的类别：</p><ul><li>家庭</li><li>社交增长</li><li>产品推广</li><li>自由职业拓展</li><li>客户工作</li><li>人际关系</li><li>健康</li></ul><p>为了排定优先级，可以考虑使用艾森豪威尔矩阵（The Eisenhower Matrix）</p><p><a href="https://www.techtello.com/eisenhower-productivity-matrix/" target="_blank" rel="noreferrer"><img src="'+a+'" alt="The Eisenhower Matrix"></a></p><p><a href="https://www.techtello.com/eisenhower-productivity-matrix/" target="_blank" rel="noreferrer">艾森豪威尔矩阵</a></p><p>如果你无法决定某件事是不是优先事项，那就抛硬币。不知道它是不是优先事项，通常意味着它不是。抛个硬币，省点脑力。</p><p>接下来几天内，每个类别下你应该会梳理出 2-5 项需要完成的任务。</p><p><strong>步骤 3) 时间分块与日程安排</strong></p><p>你知道需要做什么了，现在是时候把它定下来了。安排时间块能让你的大脑为行动做好准备。</p><p>花 10 分钟把你的任务填进日历或你最喜欢的计划表里。</p><p>工作时使用番茄工作法——专注 50 分钟，主动休息 10 分钟（离开你的椅子）。</p><p>从小处着手，逐步增加工作量。先从 1-2 小时开始，养成习惯，然后再相应增加。</p><p>安排你的时间块每周不应超过 15 分钟。</p><h3 id="joey-保持专注的快速技巧" tabindex="-1">Joey 保持专注的快速技巧 <a class="header-anchor" href="#joey-保持专注的快速技巧" aria-label="Permalink to &quot;Joey 保持专注的快速技巧&quot;">​</a></h3><p><strong>步骤 1) 通过减少不确定性来提升清晰度</strong></p><ul><li>战斗、逃跑还是僵死——没有清晰度，你就不会选择战斗。</li><li>这可以通过重新过一遍上述的步骤 1-3 来实现。</li></ul><p><strong>提示 2) 消除干扰</strong></p><ul><li>把手机调成“勿扰模式”并把它拿离桌面。</li><li>关闭不必要的浏览器标签页。</li><li>如果必须的话，离开家去外面工作（咖啡馆总是个好去处）。</li></ul><p><strong>提示 3) 音乐</strong></p><ul><li>听纯器乐而不是带歌词的音乐</li><li>电影或你最喜欢的电子游戏原声带</li><li>《星际穿越》、《黑暗骑士》或汉斯·季默（Hans Zimmer）的任何作品都有奇效</li><li>合成器波音乐（Synthwave）</li></ul><p><strong>提示 4) 照顾好自己</strong></p><ul><li>多活动（锻炼）</li><li>吃得更好</li><li>保证高质量的睡眠（绝对至关重要）</li><li>优先考虑恢复（心理和生理）</li></ul><p>你无法强迫疲惫的大脑去工作。你的脑力表现必须是可持续的。</p><h2 id="做出承诺" tabindex="-1">做出承诺 <a class="header-anchor" href="#做出承诺" aria-label="Permalink to &quot;做出承诺&quot;">​</a></h2><p>如果你在读这篇文章，说明你很有野心。</p><p>你想要建立一些能在财务、心理或生理上提高你生活质量的东西。</p><p>这就是起点。</p><p>对非对称下注做出承诺。</p><p>对专注做出承诺。</p><p>—</p><p>Joey 关于专注工作的技巧取自我们一起在 <a href="https://join.modernmastery.co/" target="_blank" rel="noreferrer">Modern Mastery HQ</a> 所做的一项培训。这些技巧与 <a href="https://learn.thedankoe.com/planner" target="_blank" rel="noreferrer">The Power Planner</a> 是绝佳搭配。</p><p>你也可以去听听我和 Joey 合作的播客：<a href="https://www.modernmastery.co/post/you-are-not-5-friends-psypreneur" target="_blank" rel="noreferrer">你并非你身边 5 个朋友的总和</a>。</p><hr><p><a href="/en/letters/4-hours-of-focused-work-will-change-your-life">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',75))])}const T=o(u,[["render",f]]);export{y as __pageData,T as default};
